import pyotp
import pytest

import app.auth as auth_module
from app.auth import AuthError, get_session, login, otp_header, verificar_otp

ALICE_SECRET = "JBSWY3DPEHPK3PXP"


def _otp(secret: str = ALICE_SECRET) -> str:
    return pyotp.TOTP(secret).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", _otp())
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", _otp())
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", _otp())


def test_login_otp_incorrecto_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_sustituyendo_verificar_otp(monkeypatch):
    monkeypatch.setattr(auth_module, "verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "cualquier-cosa")
    assert s.username == "alice"


def test_verificar_otp_directo():
    assert verificar_otp("alice", _otp()) is True
    assert verificar_otp("alice", "000000") is False
    assert verificar_otp("alice", "") is False


def test_otp_header_docstring_menciona_x_otp():
    assert "X-OTP" in otp_header.__doc__


def test_endpoint_login(client):
    otp_bob = pyotp.TOTP("KRSXG5CTMVRXEZLU").now()
    assert (
        client.post(
            "/login",
            json={"username": "bob", "password": "bob-pass", "otp": otp_bob},
        ).status_code
        == 200
    )
    assert (
        client.post(
            "/login",
            json={"username": "bob", "password": "x", "otp": otp_bob},
        ).status_code
        == 401
    )


def test_endpoint_login_sin_otp_o_invalido(client):
    assert (
        client.post(
            "/login", json={"username": "bob", "password": "bob-pass"}
        ).status_code
        == 401
    )
    assert (
        client.post(
            "/login",
            json={"username": "bob", "password": "bob-pass", "otp": "000000"},
        ).status_code
        == 401
    )

